// ─────────────────────────────────────────────────────────────────────────────
// SETTINGS — the only node you should need to edit.
// Secrets are NOT here: the webhook key and the AI key live in n8n Credentials.
// ─────────────────────────────────────────────────────────────────────────────
const SETTINGS = {
  // AI provider (any OpenAI-compatible Chat Completions API).
  ai_base_url: 'https://api.groq.com/openai/v1', // OpenAI: https://api.openai.com/v1
  ai_model: 'openai/gpt-oss-120b',               // OpenAI: gpt-4o-mini
  ai_max_tokens: 2000,

  // Knowledge Base rules (Assignment 1) used to compute facts the AI must quote, never invent.
  payout_threshold_inr: 1000, // minimum payout, applied to the author's whole account
  overdue_after_days: 90,     // brief: red badge rule

  // Idempotency: the same author (or the same request) within this window is answered "Duplicate".
  dedupe_window_seconds: 120,

  // Bonus: actually send the email over SMTP (configure the SMTP credential on "Send email (SMTP)").
  // Dataset emails are fake (@email.com), so every email goes to test_recipient instead of the author.
  send_email: false,
  test_recipient: 'you@example.com',

  // Optional second channel: PATCH the Notification Log through Bubble's Data API.
  // Off by default because Bubble's FREE plan does not include the Data API; the synchronous
  // webhook response below is the primary channel and works on every plan.
  bubble_callback: false,
  bubble_api_base: 'https://YOUR-APP.bubbleapps.io/version-test/api/1.1/obj',
};

const req = $input.first().json;
return [{ json: { settings: SETTINGS, request: req.body ?? {}, received_at: new Date().toISOString() } }];

// Validate the payload Bubble sent. Never trust a webhook body: check every field we rely on.
const { settings, request: r, received_at } = $input.first().json;
const errors = [];
const isNum = (v) => typeof v === 'number' && Number.isFinite(v);
const isDate = (v) => v == null || v === '' || /^\d{11,}$/.test(String(v).trim()) || !Number.isNaN(Date.parse(v)); // ISO, Bubble text format or epoch ms

if (!r || typeof r !== 'object') errors.push('body must be a JSON object');
if (!r?.request_id) errors.push('request_id is required (the Notification Log row id)');
if (!r?.author?.author_id) errors.push('author.author_id is required');
if (!r?.author?.name) errors.push('author.name is required');
if (!Array.isArray(r?.books)) errors.push('books must be an array');
if (r?.as_of_date && !isDate(r.as_of_date)) errors.push('as_of_date must be a date');

for (const [i, b] of (Array.isArray(r?.books) ? r.books : []).entries()) {
  if (!b?.title) errors.push(`books[${i}].title is required`);
  if (!b?.status) errors.push(`books[${i}].status is required`);
  for (const f of ['copies_sold', 'royalty_earned', 'royalty_paid', 'royalty_pending']) {
    if (b?.[f] != null && b[f] !== '' && !isNum(Number(b[f]))) errors.push(`books[${i}].${f} must be a number`);
  }
  for (const f of ['publication_date', 'last_payout_date']) if (!isDate(b?.[f])) errors.push(`books[${i}].${f} must be a date`);
}

return [{
  json: {
    ok: errors.length === 0,
    errors,
    settings,
    request: r,
    received_at,
    request_id: r?.request_id ?? null,
    author_id: r?.author?.author_id ?? null,
  },
}];

// Idempotency on the n8n side (Bubble also disables the button while a request is pending).
// Workflow static data survives between production executions of this workflow, so it can remember
// what it processed recently. A repeat of the same request_id, or the same author inside the window,
// is answered "Duplicate" without calling the AI again.
const item = $input.first().json;
const store = $getWorkflowStaticData('global');
store.recent = store.recent || {};

const now = Date.now();
const windowMs = item.settings.dedupe_window_seconds * 1000;
for (const [k, t] of Object.entries(store.recent)) if (now - t > windowMs) delete store.recent[k]; // expire old keys

const keys = [`req:${item.request_id}`, `author:${item.author_id}`];
const hit = keys.find((k) => store.recent[k]);
if (!hit) for (const k of keys) store.recent[k] = now;

return [{ json: { ...item, duplicate: Boolean(hit), duplicate_reason: hit ? (hit.startsWith('req:') ? 'same request already processed' : `a summary for this author was already requested in the last ${item.settings.dedupe_window_seconds} seconds`) : null } }];

// Compute every number, date and status the email may mention, deterministically, from the payload.
// The AI writes the words; this node decides the facts. Totals are recomputed here rather than trusted
// from the caller, and the payout rules come from the Assignment 1 Knowledge Base.
const item = $input.first().json;
const { settings, request: r } = item;

const DAY = 86_400_000;
const num = (v) => (v == null || v === '' ? 0 : Number(v));
// Bubble may send plain dates ("2024-07-05"), full timestamps or its own formats; normalise all to UTC midnight.
// Bubble stores a date as local midnight of the app's timezone, e.g. 15 Oct 2025 in India arrives as
// "2025-10-14T18:30:00Z" (or epoch ms). Rounding a timestamp to the nearest UTC day recovers the calendar date
// for any offset within ±12 h, so the email never shows a date one day early.
const toDate = (v) => {
  if (v == null || v === '') return null;
  const s = String(v).trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return new Date(s + 'T00:00:00Z');
  const ms = /^\d{11,}$/.test(s) ? Number(s) : (/^\d{4}-\d{2}-\d{2}T/.test(s) ? Date.parse(s) : NaN);
  if (!Number.isNaN(ms)) return new Date(Math.round(ms / DAY) * DAY);
  const t = new Date(s);
  return Number.isNaN(t.getTime()) ? null : new Date(Date.UTC(t.getFullYear(), t.getMonth(), t.getDate()));
};
const iso = (d) => (d ? d.toISOString().slice(0, 10) : null);
const inr = (n) => '₹' + Math.round(n).toLocaleString('en-IN');
const STAGES = ['Manuscript Received', 'Editing', 'Cover Design', 'Typesetting', 'Proofreading', 'ISBN Assignment', 'Printing', 'Distribution Setup', 'Published & Live'];

const asOf = toDate(r.as_of_date) ?? toDate(new Date().toISOString());

// Quarterly cycle, paid within 45 days of quarter end: Q1→14 May, Q2→14 Aug, Q3→14 Nov, Q4→14 Feb (next year).
function payoutDeadlines(year) {
  const ends = [[2, 31], [5, 30], [8, 30], [11, 31]]; // Mar 31, Jun 30, Sep 30, Dec 31 (0-based months)
  return ends.map(([m, d]) => new Date(Date.UTC(year, m, d) + 45 * DAY));
}
function nextPayout(from) {
  for (const y of [from.getUTCFullYear() - 1, from.getUTCFullYear(), from.getUTCFullYear() + 1]) {
    for (const due of payoutDeadlines(y)) if (due >= from) return due;
  }
  return payoutDeadlines(from.getUTCFullYear() + 1)[3];
}

const books = (r.books ?? []).map((b) => ({
  title: String(b.title).trim(),
  book_id: b.book_id ?? null,
  status: String(b.status).trim(),
  published: String(b.status).trim() === 'Published & Live',
  publication_date: toDate(b.publication_date),
  copies_sold: num(b.copies_sold),
  royalty_earned: num(b.royalty_earned),
  royalty_paid: num(b.royalty_paid),
  royalty_pending: num(b.royalty_pending),
  last_payout_date: toDate(b.last_payout_date),
  platforms: Array.isArray(b.platforms) ? b.platforms : String(b.platforms ?? '').split(',').map((s) => s.trim()).filter(Boolean),
}));

const published = books.filter((b) => b.published);
const inProduction = books.filter((b) => !b.published);
const totals = {
  earned: published.reduce((s, b) => s + b.royalty_earned, 0),
  paid: published.reduce((s, b) => s + b.royalty_paid, 0),
  pending: published.reduce((s, b) => s + b.royalty_pending, 0),
  copies: published.reduce((s, b) => s + b.copies_sold, 0),
};
const belowThreshold = totals.pending > 0 && totals.pending < settings.payout_threshold_inr;
const next = nextPayout(asOf);

for (const b of published) {
  if (b.royalty_pending <= 0) b.state = 'paid_up';
  else if (belowThreshold) b.state = 'pending_below_threshold';
  else if (b.last_payout_date && (asOf - b.last_payout_date) / DAY > settings.overdue_after_days) b.state = 'overdue';
  else if (!b.last_payout_date && b.publication_date && (asOf - b.publication_date) / DAY > settings.overdue_after_days) b.state = 'overdue';
  else b.state = 'pending';
}
for (const b of inProduction) {
  const i = STAGES.findIndex((s) => b.status.toLowerCase().includes(s.toLowerCase()));
  b.stage = i >= 0 ? STAGES[i] : b.status.replace(/^In Production\s*-\s*/i, '');
  b.remaining_stages = i >= 0 ? STAGES.slice(i + 1) : [];
}

const overdue = published.filter((b) => b.state === 'overdue');
const onSchedule = published.filter((b) => b.state === 'pending');
const scenario = !published.length ? 'nothing_published'
  : totals.pending === 0 ? 'all_paid'
  : belowThreshold ? 'below_threshold'
  : overdue.length ? (onSchedule.length ? 'overdue_and_pending' : 'overdue')
  : 'pending_on_schedule';

// FACTS block for the prompt: one fact per line, every value already formatted the way the email should show it.
const L = [];
L.push(`AS_OF_DATE: ${iso(asOf)}`);
L.push(`AUTHOR: ${r.author.name} (first name: ${String(r.author.name).trim().split(/\s+/)[0]})`);
L.push(`SCENARIO: ${scenario}`);
for (const b of published) {
  const last = b.last_payout_date ? iso(b.last_payout_date) : 'never paid yet';
  L.push(`PUBLISHED_BOOK: "${b.title}" | ${b.copies_sold} copies sold | earned ${inr(b.royalty_earned)} | paid ${inr(b.royalty_paid)} | pending ${inr(b.royalty_pending)} | last payout ${last} | state ${b.state}`);
}
for (const b of inProduction) {
  L.push(`IN_PRODUCTION: "${b.title}" | current stage ${b.stage}${b.remaining_stages.length ? ` | still to come: ${b.remaining_stages.join(' → ')}` : ''}`);
}
L.push(`TOTALS (published books): earned ${inr(totals.earned)} | paid ${inr(totals.paid)} | pending ${inr(totals.pending)}`);
if (scenario === 'all_paid') L.push('PAYOUT: everything earned so far has been paid. Thank them; there is nothing outstanding.');
if (onSchedule.length) L.push(`NEXT_PAYOUT_DATE: ${iso(next)} — applies to the on-schedule pending amount${onSchedule.length < published.length ? ` (${onSchedule.map((b) => `"${b.title}"`).join(', ')})` : ''}. Royalties are calculated quarterly and paid within 45 days of the quarter ending.`);
if (belowThreshold) L.push(`BELOW_MINIMUM: total pending ${inr(totals.pending)} is below the ${inr(settings.payout_threshold_inr)} minimum payout, so it rolls over to the next quarter; it is paid once the account total reaches ${inr(settings.payout_threshold_inr)}. Do NOT call this overdue and do not promise a payout date for it.`);
if (overdue.length) L.push(`REQUIRED_ACTION: the pending royalty for ${overdue.map((b) => `"${b.title}"`).join(', ')} is overdue, and that is BookLeaf's responsibility. Say so plainly ("this is on us"), say it has been escalated to our finance team, and promise an update within 48 hours. Do NOT tell the author to wait for a future payout date for these books.`);
L.push('NOT_IN_DATA: bank account details, per-platform sales breakdown, printing/commission/shipping costs per copy');

// Values the email is allowed to state; anything else is flagged by the fact-check node.
const amounts = new Set([totals.earned, totals.paid, totals.pending, settings.payout_threshold_inr]);
for (const b of published) [b.royalty_earned, b.royalty_paid, b.royalty_pending].forEach((v) => amounts.add(Math.round(v)));
const dates = new Set([iso(asOf)]);
if (onSchedule.length) dates.add(iso(next));
for (const b of books) [b.publication_date, b.last_payout_date].forEach((d) => d && dates.add(iso(d)));

return [{
  json: {
    ...item,
    facts: {
      as_of_date: iso(asOf),
      scenario,
      first_name: String(r.author.name).trim().split(/\s+/)[0],
      totals,
      next_payout_date: onSchedule.length ? iso(next) : null,
      overdue_titles: overdue.map((b) => b.title),
      in_production_titles: inProduction.map((b) => b.title),
      published_titles: published.map((b) => b.title),
      lines: L,
      allowed_amounts: [...amounts],
      allowed_dates: [...dates],
    },
  },
}];

// Parse and fact-check the AI's email before anyone sees it. The prompt *asks* for accuracy; this node
// *checks* it: every rupee amount and date in the email must come from the facts we computed.
// Invented figures or dates fail the run (status "Failed"); softer issues become warnings.
const ctx = $('Build AI prompt').first().json;
const { facts } = ctx;
const res = $input.first().json;

const fail = (message, raw) => [{ json: { ok: false, stage: 'ai_output_check', error_message: message, raw: raw ? String(raw).slice(0, 500) : null } }];

let content = res?.choices?.[0]?.message?.content;
if (!content) return fail('The AI returned an empty response.', JSON.stringify(res));
content = String(content).trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();

let out;
try {
  out = JSON.parse(content);
} catch {
  const m = content.match(/\{[\s\S]*\}/); // tolerate stray text around the JSON object
  try { out = m ? JSON.parse(m[0]) : null; } catch { out = null; }
}
if (!out || typeof out.subject !== 'string' || typeof out.body !== 'string') return fail('The AI response was not the expected JSON {subject, body}.', content);

// Normalise: plain text, plain spaces (reasoning models like U+202F narrow spaces), no markdown emphasis.
const clean = (s) => s.replace(/[    ]/g, ' ').replace(/[‐‑]/g, '-').replace(/\*\*|__/g, '').replace(/^#+\s*/gm, '').trim();
const subject = clean(out.subject).slice(0, 120);
let body = clean(out.body);
if (body.length < 200) return fail('The AI email body is too short to be a useful summary.', body);

// ── fact check ──
const MONTHS = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];
const MONTH_RE = '(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|june?|july?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)';
const pad = (n) => String(n).padStart(2, '0');
const isoOf = (y, m, d) => `${y}-${pad(m)}-${pad(d)}`;
const mi = (s) => MONTHS.indexOf(s.slice(0, 3).toLowerCase()) + 1;

const amounts = [...body.matchAll(/(?:₹|Rs\.?\s?|INR\s?)\s*([\d,]+(?:\.\d+)?)/gi)].map((m) => Math.round(Number(m[1].replace(/,/g, ''))));
const dates = new Set();
for (const m of body.matchAll(/\b(\d{4})-(\d{2})-(\d{2})\b/g)) dates.add(isoOf(m[1], +m[2], +m[3]));
for (const m of body.matchAll(new RegExp(`\\b(\\d{1,2})(?:st|nd|rd|th)?\\s+${MONTH_RE}\\.?,?\\s+(\\d{4})\\b`, 'gi'))) dates.add(isoOf(m[3], mi(m[2]), +m[1]));
for (const m of body.matchAll(new RegExp(`\\b${MONTH_RE}\\.?\\s+(\\d{1,2})(?:st|nd|rd|th)?,?\\s+(\\d{4})\\b`, 'gi'))) dates.add(isoOf(m[3], mi(m[1]), +m[2]));

const allowedAmounts = new Set(facts.allowed_amounts.map((n) => Math.round(n)));
const allowedDates = new Set(facts.allowed_dates);
const badAmounts = [...new Set(amounts.filter((a) => !allowedAmounts.has(a)))];
const badDates = [...dates].filter((d) => !allowedDates.has(d));
if (badAmounts.length || badDates.length) {
  const parts = [];
  if (badAmounts.length) parts.push(`amounts not in the author's data: ${badAmounts.map((a) => '₹' + a.toLocaleString('en-IN')).join(', ')}`);
  if (badDates.length) parts.push(`dates not in the author's data: ${badDates.join(', ')}`);
  return fail(`AI email failed the fact check (${parts.join('; ')}). Nothing was sent.`, body);
}

// ── softer checks: reported to the admin, do not block ──
const warnings = [];
const lower = body.toLowerCase();
if (!lower.includes(facts.first_name.toLowerCase())) warnings.push('Greeting does not use the author\'s first name.');
for (const t of facts.published_titles) if (!lower.includes(t.toLowerCase())) warnings.push(`Published book "${t}" is not mentioned.`);
for (const t of facts.in_production_titles) if (!lower.includes(t.toLowerCase())) warnings.push(`In-production book "${t}" has no status update.`);
if (!facts.in_production_titles.length && /\bproduction\b/i.test(body)) warnings.push('Mentions production although no book is in production.');
if (facts.overdue_titles.length && !/finance/i.test(body)) warnings.push('Overdue royalty is not escalated to finance.');
if (facts.scenario === 'overdue' && /next (regular )?payout|upcoming payout/i.test(body)) warnings.push('Overdue author is pointed to a future payout cycle.');
if (/warm regards|best regards|sincerely|yours truly/i.test(body)) body = body.replace(/\n+(warm regards|best regards|sincerely|yours truly)[\s\S]*$/i, '').trim(); // we add the signature
const words = body.split(/\s+/).length;
if (words > 380) warnings.push(`Email is long (${words} words).`);

body += '\n\nWarm regards,\nThe BookLeaf Author Support Team\nBookLeaf Publishing';

return [{
  json: {
    ok: true,
    subject,
    body,
    warnings,
    words,
    model: res.model ?? ctx.settings.ai_model,
    usage: res.usage ? { prompt_tokens: res.usage.prompt_tokens, completion_tokens: res.usage.completion_tokens } : null,
  },
}];

// Shape the Success response that Bubble writes into the Notification Log.
const ctx = $('Validate payload').first().json;
const email = $('Fact-check AI email').first().json;
const sent = $input.first().json; // from "Send email (SMTP)" when enabled, otherwise the fact-check output

const emailSent = ctx.settings.send_email ? !sent.error : false;
const warnings = [...email.warnings];
if (ctx.settings.send_email && sent.error) warnings.push(`SMTP send failed: ${String(sent.error.message ?? sent.error).slice(0, 160)}. The email content is still logged.`);

return [{
  json: {
    response: {
      status: 'Success',
      request_id: ctx.request_id,
      author_id: ctx.author_id,
      subject: email.subject,
      body: email.body,
      warnings,
      warnings_text: warnings.join(' | '), // the same warnings as one text field, which is easy to store in Bubble
      email_sent: emailSent,
      sent_to: emailSent ? ctx.settings.test_recipient : null,
      model: email.model,
      stage: '',          // same keys as the failure response, so Bubble's API Connector sees one shape
      error_message: '',
      completed_at: new Date().toISOString(),
    },
  },
}];

// One place that turns any failure into the same "Failed" response, so Bubble always gets an answer
// (no spinner forever) and the Notification Log records why. Reached from: invalid payload, duplicate,
// the AI call's error output, and the fact-check rejecting the email.
const ctx = $('Validate payload').first().json;
const input = $input.first().json;

let status = 'Failed';
let stage;
let message;
let httpCode = 200; // business failures are a normal answer for Bubble to log; only malformed requests get 4xx

if (input.duplicate) {
  status = 'Duplicate';
  stage = 'dedupe';
  message = `Not sent again: ${input.duplicate_reason}.`;
} else if (input.ok === false && input.errors) {
  stage = 'validation';
  message = `Invalid request from Bubble: ${input.errors.join('; ')}`;
  httpCode = 400;
} else if (input.stage === 'ai_output_check') {
  stage = 'ai_output_check';
  message = input.error_message;
} else {
  // Error output of the HTTP Request node (AI API down, timeout, 401/429/5xx after retries).
  const e = input.error ?? input;
  const code = e.httpCode ?? e.status ?? e.cause?.status ?? null;
  stage = 'ai_api';
  message = `AI service call failed${code ? ` (HTTP ${code})` : ''}: ${String(e.message ?? e.description ?? 'unknown error').slice(0, 200)}`;
}

// A failed attempt must not block a retry: release the per-author de-duplication lock so the admin can try
// again straight away (the request_id stays recorded, so the very same request is still never processed twice).
if (stage === 'ai_api' || stage === 'ai_output_check') {
  const store = $getWorkflowStaticData('global');
  if (store.recent && ctx?.author_id) delete store.recent[`author:${ctx.author_id}`];
}

return [{
  json: {
    http_code: httpCode,
    response: {
      status,
      request_id: ctx?.request_id ?? null,
      author_id: ctx?.author_id ?? null,
      stage,
      error_message: message,
      // same keys as the success response, so Bubble's API Connector sees one response shape
      subject: '',
      body: '',
      warnings: [],
      warnings_text: '',
      email_sent: false,
      sent_to: null,
      model: '',
      completed_at: new Date().toISOString(),
    },
  },
}];
